@@ -0,0 +1,10 @@
+import { agendaEntries } from './agenda.js';
+import { summarizeAttendance } from './attendance.js';
+
+export function buildOrganizerDigest(events, signupsByEvent) {
+  const lookup = signupsByEvent ?? {};
+  return agendaEntries(events).map(({ event, card }) => {
+    const signups = Object.hasOwn(lookup, card.id) ? lookup[card.id] ?? [] : [];
+    return { ...card, ...summarizeAttendance(event, signups) };
+  });
+}

